const userInput = "admin@test.com' OR '1'='1";

// --- BAD (VULNERABLE) ---
// String concatenation allows the input to alter the SQL logic.
const badQuery = `SELECT * FROM users WHERE email = '${userInput}'`;
console.log("DANGEROUS QUERY:");
console.log(badQuery);

// --- GOOD (PREPARED STATEMENT) ---
// The SQL logic is locked. The '?' acts as a placeholder.
const goodQuery = `SELECT * FROM users WHERE email = ?`;
const values = [userInput];

// The database engine receives the raw string, but knows it's strictly data, not logic.
// db.execute(goodQuery, values);
console.log("\nSAFE QUERY:");
console.log(goodQuery, "<-- Executed safely with data:", values);
